package com.xdownload.mobile;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.media.MediaMetadataRetriever;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
/** Local sequential transcode; output size is a requested estimate, not a guaranteed exact byte count. */
public final class BatchVideoActivity extends SecureActivity{
 final ExecutorService io=Executors.newSingleThreadExecutor();volatile boolean dead=false;boolean busy,en;Button pick,save;Spinner resolution;EditText target;TextView status;File result;String name;
 String tr(String a,String b){return en?b:a;}
 @Override public void onCreate(Bundle b){super.onCreate(b);en=Store.settings(this).getBoolean("english",false);ScrollView scroll=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);scroll.addView(l);TextView title=new TextView(this);title.setText(tr("استوديو الفيديو الجماعي","Batch video studio"));title.setTextSize(22);l.addView(title);resolution=new Spinner(this);resolution.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"480p","720p","1080p"}));resolution.setSelection(1);l.addView(resolution);target=new EditText(this);target.setInputType(2);target.setHint(tr("الحجم المستهدف لكل فيديو MiB (10–250)","Target per video MiB (10–250)"));target.setText("30");l.addView(target);pick=new Button(this);pick.setText(tr("اختر 1–5 فيديوهات","Choose 1–5 videos"));pick.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("video/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),1));l.addView(pick);save=new Button(this);save.setText(tr("حفظ النتيجة","Save result"));save.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(name.endsWith(".zip")?"application/zip":"video/mp4").putExtra(Intent.EXTRA_TITLE,name),2));l.addView(save);status=new TextView(this);status.setText(tr("تحويل محلي إلى MP4 (MPEG-4/AAC). الحجم تقديري؛ قد يختلف حسب المصدر. لا يتم تعديل الأصل.","Local MP4 (MPEG-4/AAC) conversion. Size is an estimate and varies by source. Originals unchanged."));l.addView(status);setContentView(scroll);state(false);}
 void state(boolean b){busy=b;pick.setEnabled(!b);resolution.setEnabled(!b);target.setEnabled(!b);save.setEnabled(!b&&result!=null);}
 void discard(){if(result!=null){result.delete();result=null;}}
 void report(String s){runOnUiThread(()->{if(!dead){status.setText(s);state(false);}});}
 static int bitrate(long durationMs,int mib)throws IOException{if(durationMs<=0||durationMs>24L*3600000||mib<10||mib>250)throw new IOException("Invalid duration or target");long available=(long)(mib*1048576L*8*0.94*1000/durationMs)-96000;if(available<128000)throw new IOException("Target too small for this duration");return (int)Math.min(12000000,available);}
 static void encode(Context c,File input,File output,int height,int mib)throws IOException{MediaMetadataRetriever r=new MediaMetadataRetriever();long duration;try{r.setDataSource(input.getPath());duration=Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));}catch(Exception e){throw new IOException("Cannot determine video duration",e);}finally{r.release();}int rate=bitrate(duration,mib);NativeMedia.run(c,"-y","-protocol_whitelist","file,pipe","-i",input.getAbsolutePath(),"-map","0:v:0","-map","0:a:0?","-vf","scale=-2:'min("+height+",ih)'","-c:v","mpeg4","-b:v",Integer.toString(rate),"-c:a","aac","-b:a","96k","-pix_fmt","yuv420p","-movflags","+faststart",output.getAbsolutePath());if(output.length()<100||output.length()>512L*1024*1024)throw new IOException("Invalid or oversized video output");}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(code!=RESULT_OK||data==null)return;if(req==2&&result!=null&&data.getData()!=null){File f=result;Uri uri=data.getData();state(true);io.execute(()->{try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(uri,"w")){AudioStudioActivity.copy(in,out);report(tr("تم الحفظ","Saved"));}catch(Exception e){report(tr("فشل الحفظ","Save failed"));}});return;}if(req!=1||busy)return;LinkedHashSet<Uri> uris=new LinkedHashSet<>();if(data.getData()!=null)uris.add(data.getData());ClipData clip=data.getClipData();if(clip!=null){if(clip.getItemCount()>5){status.setText(tr("الحد 5 فيديوهات","Maximum 5 videos"));return;}for(int i=0;i<clip.getItemCount();i++)if(clip.getItemAt(i).getUri()!=null)uris.add(clip.getItemAt(i).getUri());}if(uris.isEmpty()||uris.size()>5)return;int mib;try{mib=Integer.parseInt(target.getText().toString());if(mib<10||mib>250)throw new IllegalArgumentException();}catch(Exception e){status.setText(tr("اختر حجمًا بين 10 و250","Choose 10–250 MiB"));return;}int height=new int[]{480,720,1080}[resolution.getSelectedItemPosition()];discard();state(true);status.setText(tr("جارٍ التحويل…","Converting…"));final int selected=mib;io.execute(()->convert(uris,height,selected));}
 void convert(Collection<Uri> uris,int height,int mib){File input=null,output=null,zip=null;try{boolean batch=uris.size()>1;long total=0;int i=0;zip=batch?File.createTempFile("studio-out-",".zip",getCacheDir()):null;try(java.util.zip.ZipOutputStream archive=batch?new java.util.zip.ZipOutputStream(new BufferedOutputStream(new FileOutputStream(zip))):null){for(Uri u:uris){if(dead||Thread.currentThread().isInterrupted())throw new IOException("Cancelled");input=File.createTempFile("studio-in-",".video",getCacheDir());output=File.createTempFile("studio-out-",".mp4",getCacheDir());try(InputStream in=getContentResolver().openInputStream(u)){AudioStudioActivity.stage(in,input);}encode(this,input,output,height,mib);total+=output.length();if(total>512L*1024*1024||getCacheDir().getUsableSpace()<AudioStudioActivity.COPY_RESERVE)throw new IOException("Batch output/storage limit");i++;if(batch){archive.putNextEntry(new java.util.zip.ZipEntry("video-"+i+".mp4"));try(InputStream in=new FileInputStream(output)){AudioStudioActivity.copy(in,archive);}archive.closeEntry();output.delete();output=null;}input.delete();input=null;final int progress=i;runOnUiThread(()->{if(!dead)status.setText(progress+" / "+uris.size());});}}
 File done=batch?zip:output;if(batch)zip=null;else output=null;runOnUiThread(()->{if(dead){done.delete();return;}result=done;name=batch?"XDownload-videos.zip":"XDownload-video.mp4";status.setText(tr("جاهز للحفظ: ","Ready to save: ")+MainActivity.size(done.length()));state(false);});
 }catch(Exception|LinkageError e){report(tr("فشل التحويل: ","Conversion failed: ")+e.getMessage());}finally{if(input!=null)input.delete();if(output!=null)output.delete();if(zip!=null)zip.delete();}}
 @Override protected void onDestroy(){dead=true;io.shutdownNow();discard();super.onDestroy();}
}
